const rotationStats = `-- name: RotationStats :many
WITH served AS (
 SELECT e.staff_id, e.order_id, bool_or(e.designated) AS designated
 FROM rotation_events e
 WHERE e.store_id = $2 AND e.business_date BETWEEN $3 AND $4
  AND e.staff_id IS NOT NULL AND e.order_id IS NOT NULL
  AND e.kind IN ('advance_whole','advance_half','advance_designated_no_turn')
 GROUP BY e.staff_id, e.order_id
)
SELECT served.staff_id, s.name AS staff_name, s.number AS staff_number,
 count(*) FILTER (WHERE served.designated)::int AS designated_count,
 count(*) FILTER (WHERE NOT served.designated)::int AS rotation_count
FROM served JOIN staff s ON s.tenant_id = $1 AND s.id = served.staff_id
GROUP BY served.staff_id, s.name, s.number
ORDER BY s.number, served.staff_id
`

type RotationStatsParams struct {
	TenantID uuid.UUID
	StoreID  uuid.UUID
	FromDate pgtype.Date
	ToDate   pgtype.Date
}

type RotationStatsRow struct {
	StaffID         *uuid.UUID
	StaffName       string
	StaffNumber     string
	DesignatedCount int32
	RotationCount   int32
}

func (q *Queries) RotationStats(ctx context.Context, arg RotationStatsParams) ([]RotationStatsRow, error) {
	rows, err := q.db.Query(ctx, rotationStats,
		arg.TenantID,
		arg.StoreID,
		arg.FromDate,
		arg.ToDate,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RotationStatsRow
	for rows.Next() {
		var i RotationStatsRow
		if err := rows.Scan(
			&i.StaffID,
			&i.StaffName,
			&i.StaffNumber,
			&i.DesignatedCount,
			&i.RotationCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

